const growthById = new Map();
let rosterMode = false;
let ownedCount = 0;
if (input && Array.isArray(input.owned)) {
input.owned.forEach((entry) => { if (entry && entry.id) growthById.set(String(entry.id), entry); });
rosterMode = true;
} else {
try {
const owned = scope.NIKKE_V26_ROSTER_API && scope.NIKKE_V26_ROSTER_API.getOwned ? scope.NIKKE_V26_ROSTER_API.getOwned() : [];
if (Array.isArray(owned) && owned.length) {
